      "descricao_da_playlist": "Aprenda a criar jogos fantásticos com o Curso Unreal Engine 5 Completo. \n\nA Unreal Engine é um motor de jogo desenvolvido pela Epic Games que possui o sistema de Blueprints Visual Scripting, o que permite criar jogos inteiros sem escrever uma única linha de código!\n\nDurante o nosso curso você aprenderá muita coisa legal, como: \n- Conhecer a interface da Unreal Engine 5;\n- Trabalhar com Blueprints\n- Trabalhar com Level Blueprints\n- Criar materiais\n- Criar UI (User Interface)\n- Utilizar e criar animações\n- Utilizar recursos de áudio no jogo\n- Utilizar sistema de partículas\n- Construir jogos baseado nos estilos FPS, Corrida Infinita, plataforma e muito mais.\n\nO curso é orientado a projetos, isto é, cada vez que você criar um novo jogo você aprenderá um novo recurso da Unreal Engine. Isso torna o aprendizado mais fácil do que apenas estudando aulas pontuais relacionadas a uma determinada tecnologia.\n\nDurante o curso você poderá tirar dúvidas com o professor via plataforma. Também poderá participar de uma comunidade de desenvolvedores no Telegram a fim de compartilhar seus conhecimentos e dúvidas.\n\nUm detalhe muito legal do nosso curso é que você irá aprender a publicar seus jogos na web criando um portifólio de produtos, ao fazer isso você estará divulgando seus jogos permitindo que várias pessoas possam se divertam jogando os mesmos.\n\nEsse curso faz parte do curso Unreal Engine da plataforma Danki Code: https://go.hotmart.com/G50805821T\n\nVocê também pode encontrar esse curso em \nhttps://www.udemy.com/course/unreal_engine5/?referralCode=B53B85B567B7F4F78B49",
