      "descricao_da_playlist": "Nessa playlist você vai aprender a linguagem SQL com o Curso de SQL com MySQL que promovo como bônus em todos os meus cursos. É importante que todo dev tenha conhecimento de SQL por que isso vai fazer parte da sua rotina. Melhor ainda quando conseguimos conteúdo de qualidade e grátis.\n\nNa primeira aula, vamos falar sobre o Diagrama Entidade Relacionamento, tabelas, atributos, primary keys (chaves primárias), foreign keys (chaves estrangeiras) e muito mais. Apesar de não existir nada prático nessa aula (tudo é teórico), é uma das aulas mais importantes para o seu entendimento sobre as relações entre entidades de um sistema.",
