      "descricao_da_playlist": "Curso AWS na Prática\nDo zero até a publicação da aplicação!\n\nNesta playlist, você encontrará um Curso AWS Tutorial Completo!\nAprenda:\n- O que é AWS e Cloud Computing\n- Como criar e configurar sua conta na Amazon Web Services\n- Como controlar gastos na AWS\n- Como criar e configurar permissões de acesso com o AWS IAM\n- Como configurar uma rede privada utilizando AWS VPC\n-  Como criar e configurar um Banco de Dados com o AWS RDS\n- Como criar e configurar instâncias com o AWS EC2\n-  Como publicar uma API na AWS\n- Como configurar AWS ELB (Elastic Load Balancer)\n- Como configurar o Autoscaling na AWS\n- Como utilizar e configurar o AWS Route 53\n- Como realizar debug em Aplicações Cloud na AWS\n- O que é e como utilizar o AWS Neptune - Banco de Grafo\n- O que é, como utilizar e configurar o storage AWS S3\n- Aplicações Serverless com AWS Lambda\n- Upload de arquivos sem API de Dados utilizando AWS Lambda - Serverless\n\nTodo esse conteúdo disponível gratuitamente e de forma prática!\n\nCompartilhe esta playlis!",
